188:     /// Waits for the first handle to complete and aborts all handles before returning.
189:     ///
190:     /// Dropping the returned future also aborts every handle. Selection is biased toward handles
191:     /// that appear earlier in the iterator.
192:     ///
193:     /// Runtime supervision already aborts a task's descendants when that task exits. This method
194:     /// is intended for an owned group whose teardown boundary is the first handle completion,
195:     /// independent of whether the caller exits immediately afterward.
196:     ///
197:     /// # Examples
198:     ///
199:     /// ```
200:     /// # futures::executor::block_on(async {
201:     /// use commonware_runtime::Handle;
202:     ///
203:     /// let handles = [
204:     ///     Handle::ready(Ok(7)),
205:     ///     Handle::from_future(futures::future::pending()),
206:     /// ];
207:     /// assert_eq!(Handle::select(handles).await.unwrap(), 7);
208:     /// # });
209:     /// ```
210:     ///
211:     /// # Errors
212:     ///
213:     /// Returns [`Error::Closed`] if `handles` is empty.
214:     pub fn select(
215:         handles: impl IntoIterator<Item = Self>,
216:     ) -> impl Future<Output = Result<T, Error>> + Send + 'static {
217:         // Construct the guard before returning so dropping the future without polling still aborts
218:         // every handle.
219:         let mut handles = HandleGroup(handles.into_iter().collect::<Vec<_>>());
220: 
221:         async move {
222:             if handles.0.is_empty() {
223:                 return Err(Error::Closed);
224:             }
225: 
226:             poll_fn(move |cx| {
227:                 for handle in &mut handles.0 {
228:                     if let Poll::Ready(result) = Pin::new(handle).poll(cx) {
229:                         return Poll::Ready(result);
230:                     }
231:                 }
232:                 Poll::Pending
233:             })
234:             .await
235:         }
236:     }
